+func repairsByHref(repairs []datahelpers.LinkRepair) map[string]datahelpers.LinkRepair {
+	byHref := make(map[string]datahelpers.LinkRepair, len(repairs))
+	for _, r := range repairs { byHref[r.Href] = r }
+	return byHref
+}
+const validationWarningErrorCode = "CONTENT_VALIDATION_WARNING_DETAIL"
+func survivingWarnings(issues []ValidationIssue, repairs []datahelpers.LinkRepair) []map[string]string {
+	repaired := repairsByHref(repairs)
+	surviving := make([]map[string]string, 0, len(issues))
+	for _, issue := range issues {
+		if issue.Severity != "warning" { continue }
+		if issue.Category == "link" {
+			if _, ok := repaired[issue.Value]; ok { continue }
+		}
+		surviving = append(surviving, map[string]string{"type": issue.Type, "category": issue.Category, "severity": issue.Severity, "location": issue.Location, "value": issue.Value, "description": issue.Description})
+	}
+	return surviving
+}
+func writeValidationWarningLog(ctx context.Context, params ActionParams, siteIDStr, domain string, issues []ValidationIssue, repairs []datahelpers.LinkRepair, logger *zap.Logger) {
+	if params.DB == nil { return }
+	surviving := survivingWarnings(issues, repairs)
+	if len(surviving) == 0 { return }
+	if !LogActionEntry(ctx, params, agenterrors.Entry{
+		SiteID: siteIDArg, Domain: domain,
+		AgentType: "page-build-handler", StepName: "validate_content", Action: "validate_page_content",
+		ErrorMessage: fmt.Sprintf("Valid build carried %d unrepaired warning(s); see context.issues for detail", len(surviving)),
+		ErrorCode: validationWarningErrorCode, Severity: "warning",
+		Context: map[string]interface{}{"warning_count": len(surviving), "issues": surviving, "page_name": ..., "page_url": ...},
+	}, logger) { return }
+}

